class PresetManager
{
public:
    PresetManager(AudioProcessorValueTreeState& apvts) : apvts(apvts)
    {
        // Create presets directory if needed
        auto presetsDir = getPresetsDirectory();
        if (!presetsDir.exists())
        {
            presetsDir.createDirectory();
        }

        scanPresets();
    }

    // Get factory presets location
    File getPresetsDirectory()
    {
        return File::getSpecialLocation(File::userApplicationDataDirectory)
            .getChildFile("MyPlugin").getChildFile("Presets");
    }

    // Save current state as preset
    void savePreset(const String& name)
    {
        auto presetFile = getPresetsDirectory().getChildFile(name + ".preset");

        // Copy APVTS state
        auto state = apvts.copyState();

        // Add metadata
        DynamicObject::Ptr meta = new DynamicObject();
        meta->setProperty("name", name);
        meta->setProperty("author", "User");
        meta->setProperty("created", Time::getCurrentTime().toISO8601());

        state->setProperty("metadata", var(meta.get()));

        // Write to file
        auto xml = state.createXml();
        xml->writeTo(presetFile);

        scanPresets();
    }

    // Load preset
    void loadPreset(const File& presetFile)
    {
        auto xml = XmlDocument::parse(presetFile);
        if (xml != nullptr)
        {
            apvts.replaceState(ValueTree::fromXml(*xml));
        }
    }

    // Get all available presets
    StringArray getPresetNames()
    {
        StringArray names;
        for (auto& preset : presets)
        {
            names.add(preset.getFileNameWithoutExtension());
        }
        return names;
    }

private:
    void scanPresets()
    {
        presets.clear();
        auto presetsDir = getPresetsDirectory();
        presets = presetsDir.findChildFiles(File::findFiles, false, "*.preset");
    }

    AudioProcessorValueTreeState& apvts;
    Array<File> presets;
};

class PresetBrowser : public Component, public ComboBox::Listener
{
public:
    PresetBrowser(PresetManager& manager) : presetManager(manager)
    {
        // Preset selector
        presetSelector.setEditableText(false);
        presetSelector.addListener(this);
        addAndMakeVisible(presetSelector);

        // Navigation buttons
        prevButton.setButtonText("<");
        nextButton.setButtonText(">");
        prevButton.onClick = [this] { selectPrevious(); };
        nextButton.onClick = [this] { selectNext(); };
        addAndMakeVisible(prevButton);
        addAndMakeVisible(nextButton);

        // Save button
        saveButton.setButtonText("Save");
        saveButton.onClick = [this] { showSaveDialog(); };
        addAndMakeVisible(saveButton);

        refreshPresetList();
    }

    void resized() override
    {
        auto bounds = getLocalBounds();

        prevButton.setBounds(bounds.removeFromLeft(30));
        nextButton.setBounds(bounds.removeFromRight(30));
        saveButton.setBounds(bounds.removeFromRight(60));
        presetSelector.setBounds(bounds);
    }

    void comboBoxChanged(ComboBox* combo) override
    {
        if (combo == &presetSelector)
        {
            auto selectedId = combo->getSelectedId();
            if (selectedId > 0)
            {
                auto presetFile = presetManager.getPresetsDirectory()
                    .getChildFile(combo->getText() + ".preset");
                presetManager.loadPreset(presetFile);
            }
        }
    }

private:
    void refreshPresetList()
    {
        presetSelector.clear();
        auto names = presetManager.getPresetNames();
        int id = 1;
        for (auto& name : names)
        {
            presetSelector.addItem(name, id++);
        }
    }

    void selectPrevious()
    {
        auto current = presetSelector.getSelectedItemIndex();
        auto max = presetSelector.getNumItems() - 1;
        presetSelector.setSelectedItemIndex((current - 1 + max) % max);
    }

    void selectNext()
    {
        auto current = presetSelector.getSelectedItemIndex();
        auto max = presetSelector.getNumItems();
        presetSelector.setSelectedItemIndex((current + 1) % max);
    }

    void showSaveDialog()
    {
        AlertWindow::showAsync(
            AlertWindow::AlertIconType::QuestionIcon,
            "Save Preset",
            "Enter preset name:",
            "Save",
            "Cancel",
            nullptr,
            [this](int result, const String& name) {
                if (result == 1 && name.isNotEmpty())
                {
                    presetManager.savePreset(name);
                    refreshPresetList();
                }
            }
        );
    }

    PresetManager& presetManager;
    ComboBox presetSelector;
    TextButton prevButton, nextButton, saveButton;
};

class CategoryBrowser : public Component
{
public:
    CategoryBrowser(PresetManager& manager) : presetManager(manager)
    {
        // Category tree
        categoryTree.setTitle("Categories");
        categoryTree.setMultiSelectEnabled(false);
        addAndMakeVisible(categoryTree);

        // Preset list for selected category
        presetList.setTitle("Presets");
        addAndMakeVisible(presetList);

        // Build category tree
        buildCategoryTree();
    }

private:
    void buildCategoryTree()
    {
        auto categories = presetManager.getCategories();

        TreeViewItem* rootItem = new TreeViewItem();
        rootItem->setOpen(true);

        for (auto& category : categories)
        {
            auto* categoryItem = new CategoryTreeItem(category, presetManager);
            rootItem->addSubItem(categoryItem);
        }

        categoryTree.setRootItem(rootItem);
    }

    class CategoryTreeItem : public TreeViewItem
    {
    public:
        CategoryTreeItem(const String& cat, PresetManager& mgr)
            : category(cat), presetManager(mgr) {}

        bool canExpandItem() const override { return true; }

        void paintItem(Graphics& g, int width, int height) override
        {
            g.setColour(Colours::white);
            g.drawText(category, 5, 0, width - 10, height, Justification::left);
        }

        int getItemHeight() const override { return 25; }

    private:
        String category;
        PresetManager& presetManager;
    };

    PresetManager& presetManager;
    TreeView categoryTree;
    ListBox presetList;
};

