        // Embed presets in binary
        static const unsigned char presetData[] = {
            // ... preset binary data ...
        };

        MemoryBlock block(presetData, sizeof(presetData));
        presets.add(block);

        return presets;
    }

    static void installFactoryPresets()
    {
        auto presets = getBundledPresets();
        auto targetDir = File::getSpecialLocation(File::userApplicationDataDirectory)
            .getChildFile("MyPlugin").getChildFile("Presets").getChildFile("Factory");

        if (!targetDir.exists())
            targetDir.createDirectory();

        // Extract bundled presets
        for (int i = 0; i < presets.size(); ++i)
        {
            auto targetFile = targetDir.getChildFile("Preset" + String(i) + ".preset");
            targetFile.replaceWithData(presets[i].getData(), presets[i].getSize());
        }
    }
};

